const io = new IntersectionObserver((entries) => {
entries.forEach(e => { if (e.isIntersecting) e.target.classList.add('visible') })
}, { threshold: .12 });
reveals.forEach(el => io.observe(el));
const wrap = document.getElementById('profile3d');
if (wrap) {
wrap.parentElement.addEventListener('mousemove', e => {
const r = wrap.parentElement.getBoundingClientRect();
const x = ((e.clientX - r.left) / r.width - .5) * 20;
const y = ((e.clientY - r.top) / r.height - .5) * -20;
wrap.style.transform = `rotateY(${x}deg) rotateX(${y}deg)`;
});
wrap.parentElement.addEventListener('mouseleave', () => {
wrap.style.transform = 'rotateY(-8deg) rotateX(4deg)';
});
}
