const hScrollWrappers = document.querySelectorAll('.h-scroll-wrapper');
let scrollData = [];
hScrollWrappers.forEach((wrapper) => {
const track = wrapper.querySelector('.h-scroll-track');
const dir = track.getAttribute('data-dir') || 'forward';
scrollData.push({ wrapper, track, dir, current: 0, target: 0 });
});
window.addEventListener('scroll', () => {
scrollData.forEach(data => {
const rect = data.wrapper.getBoundingClientRect();
const scrollDistance = data.wrapper.offsetHeight - window.innerHeight;
let progress = -rect.top / scrollDistance;
progress = Math.max(0, Math.min(1, progress));
data.target = progress;
});
});
function animateScroll() {
scrollData.forEach(data => {
if (data.wrapper.classList.contains('scroll-off')) {
if (data.track) {
data.track.style.transform = '';
const slides = data.track.children;
for (let i = 0; i < slides.length; i++) {
slides[i].style.transform = '';
}
}
return;
}
const diff = data.target - data.current;
data.current += diff * 0.08;
if (data.track) {
const maxTranslate = data.track.scrollWidth - window.innerWidth;
if (maxTranslate > 0) {
let pxVelocity = diff * maxTranslate;
let targetTranslateX = 0;
if (data.dir === 'forward') {
targetTranslateX = -data.current * maxTranslate;
} else {
targetTranslateX = -maxTranslate + (data.current * maxTranslate);
}
data.track.style.transform = `translateX(${targetTranslateX}px)`;
const slides = data.track.children;
const id = data.wrapper.id;
if (id === 'thumbnails-wrapper') {
let skew = pxVelocity * 0.018;
if (skew > 15) skew = 15; if (skew < -15) skew = -15;
let scale = 1 - (Math.abs(pxVelocity) * 0.00015);
if (scale < 0.92) scale = 0.92;
let applySkew = data.dir === 'forward' ? skew : -skew;
for (let i = 0; i < slides.length; i++) {
slides[i].style.transform = `skewX(${applySkew}deg) scale(${scale})`;
}
}
else if (id === 'gaming-logos-wrapper') {
let rotY = pxVelocity * 0.08;
if (rotY > 40) rotY = 40; if (rotY < -40) rotY = -40;
let scale = 1 - (Math.abs(pxVelocity) * 0.0001);
if (scale < 0.95) scale = 0.95;
let applyRotY = data.dir === 'forward' ? -rotY : rotY;
for (let i = 0; i < slides.length; i++) {
slides[i].style.transform = `perspective(1000px) rotateY(${applyRotY}deg) scale(${scale})`;
}
}
else if (id === 'short-thumbnails-wrapper') {
let bob = Math.abs(pxVelocity) * 0.15;
if (bob > 40) bob = 40;
let scale = 1 - (Math.abs(pxVelocity) * 0.0001);
if (scale < 0.95) scale = 0.95;
for (let i = 0; i < slides.length; i++) {
let dir = i % 2 === 0 ? 1 : -1;
slides[i].style.transform = `translateY(${bob * dir}px) scale(${scale})`;
}
}
}
}
});
requestAnimationFrame(animateScroll);
}
const scrollToggles = document.querySelectorAll('.scroll-checkbox');
scrollToggles.forEach(toggle => {
toggle.addEventListener('change', (e) => {
const targetId = e.target.getAttribute('data-target');
const wrapper = document.getElementById(targetId);
const stickyContainer = wrapper.querySelector('.sticky-container');
const stickyTopBefore = stickyContainer ? stickyContainer.getBoundingClientRect().top : 0;
if (e.target.checked) {
wrapper.classList.remove('scroll-off');
const rect = wrapper.getBoundingClientRect();
const scrollDistance = wrapper.offsetHeight - window.innerHeight;
let progress = -rect.top / scrollDistance;
const sData = scrollData.find(d => d.wrapper.id === targetId);
if (sData) {
sData.current = Math.max(0, Math.min(1, progress));
if (stickyContainer) stickyContainer.scrollLeft = 0;
}
} else {
wrapper.classList.add('scroll-off');
const sData = scrollData.find(d => d.wrapper.id === targetId);
if (sData && sData.track) sData.track.style.transform = `translate3d(0, 0, 0)`;
}
setTimeout(() => {
if (stickyContainer) {
const stickyTopAfter = stickyContainer.getBoundingClientRect().top;
window.scrollBy({ top: stickyTopAfter - stickyTopBefore, behavior: 'instant' });
} else {
wrapper.scrollIntoView({ behavior: 'instant', block: 'start' });
}
}, 10);
});
});
