(function () {
let lbImages = [];
let lbIndex = 0;
let touchStartX = 0;
function buildImageList() {
lbImages = [];
document.querySelectorAll('.work-slide .p-card, .logo-slide .p-card, .short-slide .p-card').forEach(card => {
const img = card.querySelector('img');
const type = card.querySelector('.p-card-type');
if (!img || !img.src) return;
if (card.querySelector('.p-card-title') && card.querySelector('.p-card-title').textContent.trim() === '') return;
lbImages.push({
src: img.src,
alt: img.alt || 'Portfolio Image',
label: type ? type.textContent.trim() : 'Portfolio'
});
});
}
function openLightbox(idx) {
buildImageList();
if (!lbImages.length) return;
lbIndex = Math.max(0, Math.min(idx, lbImages.length - 1));
setLightboxImage(lbIndex, false);
document.getElementById('lightbox').classList.add('open');
document.body.style.overflow = 'hidden';
}
function closeLightbox() {
document.getElementById('lightbox').classList.remove('open');
document.body.style.overflow = '';
}
function setLightboxImage(idx, animate) {
const item = lbImages[idx];
if (!item) return;
const wrap = document.getElementById('lbImgWrap');
const img = document.getElementById('lbMainImg');
const counter = document.getElementById('lbCounter');
const label = document.getElementById('lbLabel');
counter.textContent = (idx + 1) + ' / ' + lbImages.length;
label.textContent = item.label;
if (animate) {
wrap.classList.add('switching');
setTimeout(() => {
img.src = item.src;
img.alt = item.alt;
wrap.classList.remove('switching');
}, 180);
} else {
img.src = item.src;
img.alt = item.alt;
}
}
function lbNext() { lbIndex = (lbIndex + 1) % lbImages.length; setLightboxImage(lbIndex, true); }
function lbPrev() { lbIndex = (lbIndex - 1 + lbImages.length) % lbImages.length; setLightboxImage(lbIndex, true); }
function attachCardClicks() {
buildImageList();
let globalIdx = 0;
document.querySelectorAll('.work-slide .p-card, .logo-slide .p-card, .short-slide .p-card').forEach(card => {
const img = card.querySelector('img');
if (!img || !img.src) return;
if (card.getAttribute('onclick') && card.getAttribute('onclick').includes('openGallery')) return;
const capturedIdx = globalIdx;
card.style.cursor = 'pointer';
card.addEventListener('click', (e) => {
if (e.target.tagName === 'BUTTON' || e.target.closest('button')) return;
openLightbox(capturedIdx);
});
globalIdx++;
});
}
document.addEventListener('keydown', (e) => {
const lb = document.getElementById('lightbox');
if (!lb.classList.contains('open')) return;
if (e.key === 'ArrowRight' || e.key === 'ArrowDown') lbNext();
if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') lbPrev();
if (e.key === 'Escape') closeLightbox();
});
document.getElementById('lightbox').addEventListener('touchstart', e => {
touchStartX = e.touches[0].clientX;
}, { passive: true });
document.getElementById('lightbox').addEventListener('touchend', e => {
const dx = e.changedTouches[0].clientX - touchStartX;
if (Math.abs(dx) > 50) { dx < 0 ? lbNext() : lbPrev(); }
}, { passive: true });
document.getElementById('lightbox').addEventListener('click', (e) => {
if (e.target === document.getElementById('lightbox')) closeLightbox();
});
window.openLightbox = openLightbox;
window.closeLightbox = closeLightbox;
window.lbNext = lbNext;
window.lbPrev = lbPrev;
attachCardClicks();
})();
window.addEventListener('scroll', () => {
const grid = document.querySelector('.services-grid');
const timelineProgress = document.getElementById('timelineProgress');
if (!grid || !timelineProgress) return;
const rect = grid.getBoundingClientRect();
const windowH = window.innerHeight;
const triggerPoint = windowH * 0.6;
if (rect.top > triggerPoint) {
timelineProgress.style.height = '0%';
} else {
let scrollPx = triggerPoint - rect.top;
let maxScroll = rect.height;
let progress = (scrollPx / maxScroll) * 100;
progress = Math.max(0, Math.min(100, progress));
timelineProgress.style.height = progress + '%';
const cards = grid.querySelectorAll('.s-card');
cards.forEach(card => {
const cardRect = card.getBoundingClientRect();
const cardMid = cardRect.top + (cardRect.height / 2);
if (cardMid <= triggerPoint) {
card.classList.add('active');
} else {
card.classList.remove('active');
}
});
}
});